    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.role_changed", (payload) => resolve(payload));
      void memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "member",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      from: "admin",
      to: "member",
    });
  });

  // Removing the last owner is refused for the same invariant.
  it("refuses to remove the last remaining owner", async () => {
    const tenant = await createTenant("member-last-owner-remove", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // member.removed carries the memberId and userId that left.
  it("emits member.removed when a member is removed", async () => {
    const tenant = await createTenant("member-remove-emit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.removed", (payload) => resolve(payload));
      void memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      userId: tenant.userIds.viewer,
    });
  });

  // A suspended member keeps their row and role, but resolves to no actor.
  it("suspends and reinstates a member, emitting an event for each", async () => {
    const tenant = await createTenant("member-suspend-roundtrip", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    const suspended = await memberService.suspendMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(suspended).toMatchObject({ status: "suspended", role: "viewer" });
    await expect(
      resolveActor(tenant.userIds.viewer, tenant.org.id),
    ).resolves.toBeNull();

    const reinstated = await memberService.reinstateMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: target.id,
    });
    expect(reinstated.status).toBe("active");
    await expect(
      resolveActor(tenant.userIds.viewer, tenant.org.id),
    ).resolves.toMatchObject({ role: "viewer" });
  });

  // Suspending the only non-suspended owner would leave the workspace unownable.
  it("refuses to suspend the last owner who is not suspended", async () => {
    const tenant = await createTenant("member-suspend-last-owner", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.suspendMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // Nobody may suspend themselves.
  it("refuses to let an actor suspend themselves", async () => {
    const tenant = await createTenant("member-suspend-self", "growth");
    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!adminMember) throw new Error("fixture member missing");

    await expect(
      memberService.suspendMember(tenant.actors.admin, {
        orgId: tenant.org.id,
        memberId: adminMember.id,
      }),
    ).rejects.toThrow(/yourself/);
  });
});
